public boolean remove(int val) {
    int hash = Math.abs(val % capacity);
    while (table[hash] != null && table[hash].val != val) {
        hash = (hash + 1) % capacity;
    }
    if (table[hash] == null) {
        return false;
    }
    table[hash] = null;
    size--;
    if (size < capacity / 4) {
        resize(capacity / 2);
    }
    return true;
}

