private void pop(final String descriptor) {
        final int start = descriptor.indexOf('(');
        if (start == -1) {
            // It's a type descriptor, pop one frame
            outputFrameStack.pop();
            return;
        }

        final int end = descriptor.indexOf(')', start + 1);
        if (end == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
        }

        // Parse the argument types between '(' and ')'
        final String args = descriptor.substring(start + 1, end);
        int index = 0;
        while (index < args.length()) {
            final char c = args.charAt(index);
            switch (c) {
                case 'B': // byte
                case 'C': // char
                case 'D': // double
                case 'F': // float
                case 'I': // int
                case 'J': // long
                case 'S': // short
                case 'Z': // boolean
                    // These are each one frame
                    outputFrameStack.pop();
                    index++;
                    break;
                case 'L': // reference type
                    // Find the semicolon
                    final int semicolon = args.indexOf(';', index);
                    if (semicolon == -1) {
                        throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
                    }
                    outputFrameStack.pop();
                    index = semicolon + 1;
                    break;
                case '[': // array
                    // Just skip the '[' and process the next type descriptor
                    outputFrameStack.pop();
                    index++;
                    break;
                default:
                    throw new IllegalArgumentException("Unexpected character in method descriptor: " + c);
            }
        }
    }

