                    outputFrameStack.pop();
                    index++;
                    break;
                case 'L': // reference type
                    // Find the semicolon
                    final int semicolon = args.indexOf(';', index);
                    if (semicolon == -1) {
                        throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
                    }
                    outputFrameStack.pop();
                    index = semicolon + 1;
                    break;
                case '[': // array
                    // Just skip the '[' and process the next type descriptor
                    outputFrameStack.pop();
                    index++;
                    break;
                default:
                    throw new IllegalArgumentException("Unexpected character in method descriptor: " + c);
            }
        }
