private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices.size() < 2) {
        return true;
    }
    for (V v : vertices) {
        Set<V> adjacency = new HashSet<>(graph.getAdjacencySet(v));
        for (V u : vertices) {
            if (!v.equals(u) && !adjacency.contains(u)) {
                return false;
            }
        }
    }
    return true;
}

