private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int c1 = bb.get(i) & 0xff;
    int c;
    int count;
    int check;
    boolean topBit;

    // Determine the number of bytes in the UTF-8 sequence
    if (c1 < 0x80) {
        return i + 1; // Single-byte character
    } else if (c1 < 0xC0) {
        throw new IllegalArgumentException("Invalid UTF-8 encoding");
    } else if (c1 < 0xE0) {
        count = 2;
        c = c1 - 0xC0;
    } else if (c1 < 0xF0) {
        count = 3;
        c = c1 - 0xE00;
    } else if (c1 < 0xF8) {
        count = 4;
        c = c1 - 0xF000;
        check = c;

        // Check for valid Unicode range
        if (c < 0x100) {
            throw new IllegalArgumentException("Code point out of range");
        }
    } else {
        throw new IllegalArgumentException("Invalid UTF-8 encoding");
    }

    // Read the continuation bytes
    for (int j = 1; j < count; j++) {
        int byteValue = bb.get(i + j) & 0xff;
        if ((byteValue & 0xC0) != 0x80) {
            throw new IllegalArgumentException("Invalid UTF-8 continuation byte");
        }
        c = (c << 6) | (byteValue & 0x3F);
    }

    // Check for surrogates (5 or 6 byte sequences are not valid)
    if (count == 4) {
        if (c < 0x10000 || c > 0x10FFFF) {
            throw new IllegalArgumentException("Invalid Unicode code point");
        }
    } else if (c >= 0xD800 && c <= 0xDFFF) {
        throw new IllegalArgumentException("Invalid surrogate code point");
    }

    sb.append((char) c);
    return i + count;
}

