public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    final int len = str.length();
    final StringBuilder buf = new StringBuilder(len);
    for (int i = 0; i < len; i++) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            if (i >= (len - 1)) {
                buf.append(ch);
                continue;
            }
            final char nextCh = str.charAt(++i);
            if (nextCh != '/') {
                ch = (char) unescapeJavaChar(nextCh);
            }
        }
        buf.append(ch);
    }
    return buf.toString();
}

