public void readFrom(final InputStream in) throws IOException {
    if (in == null) {
        throw new IOException("Input stream is null");
    }
    if (buffer == null || buffer.length == 0) {
        // If buffer is not allocated, we may need to handle that case
        throw new IOException("Buffer is not allocated");
    }
    int offset = 0;
    while (offset < buffer.length) {
        int read = in.read(buffer, offset, buffer.length - offset);
        if (read == -1) {
            break;
        }
        offset += read;
    }
    if (offset != buffer.length) {
        throw new IOException("Could not read enough bytes into the buffer");
    }
    this.readPtr = 0;
    this.writePtr = offset;
}

