    if (value == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < value.length()) {
        if (value.charAt(i) == '$') {
            if (i + 1 < value.length() && value.charAt(i + 1) == '{') {
                int end = value.indexOf('}', i + 2);
                if (end != -1) {
                    String innerKey = value.substring(i + 2, end);
                    String innerValue = findAndSubst(innerKey, props);
                    if (innerValue != null) {
                        result.append(innerValue);
                    }
                    i = end + 1;
                } else {
                    result.append(value.charAt(i));
                    i++;
                }
            } else if (i + 2 < value.length() && value.charAt(i + 1) == '${' && value.charAt(i + 2) == '{') {
                result.append(value, i, i + 3);
                i += 3;
            } else {
                result.append(value.charAt(i));
                i++;
            }
        } else {
            result.append(value.charAt(i));
            i++;
        }
    }
    return result.toString();
}

