public void overrideName(String oldName, String newName) {
    if (oldName == null || newName == null) {
        return;
    }
    String[] parts = oldName.split("\\.");
    String columnPart = parts.length > 1 ? parts[parts.length - 1] : oldName;
    String tablePart = parts.length > 1 ? parts[0] : "";
    if (tablePart.isEmpty()) {
        if (columnPart.equals(oldName)) {
            // If the old name is just a column name, replace occurrence in all columns
            for (Column col : columns) {
                if (col.name.equals(oldName)) {
                    col.name = newName;
                }
            }
        }
    } else {
        // Handle table.column case
        for (Column col : columns) {
            String fullName = tablePart + "." + col.name;
            if (fullName.equals(oldName) || col.name.equals(oldName)) {
                col.name = newName;
            }
        }
    }
}

