public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = 0; i < len; i++) {
        int cp = str.charAt(index + i);
        if (cp <= 0x7F) {
            size += 1;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else if (Character.isSurrogate(cp)) {
            if (i < len - 1) {
                int nextCp = str.charAt(index + i + 1);
                if (Character.isTrailSurrogate(nextCp)) {
                    size += 4;
                    i++;
                } else {
                    size += 3;
                }
            } else {
                size += 3;
            }
        } else {
            size += 3;
        }
    }
    return size;
}

