public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || str.length() == 0) {
        return lb;
    }

    final int len = str.length();
    final byte[] utf8Bytes = str.toString().getBytes(Charset.forName("UTF-8"));

    if (utf8Bytes == null || utf8Bytes.length == 0) {
        return lb;
    }

    final int available = lb.writeSpace();

    if (available < utf8Bytes.length) {
        if (session == null) {
            throw new IllegalArgumentException("Session must not be null when buffer write space is insufficient");
        }
        // Extend the buffer
        final int requiredCapacity = available < utf8Bytes.length ? utf8Bytes.length : utf8Bytes.length - available;
        session.extendBuffer(requiredCapacity);
    }

    if (lb.writeSpace() >= utf8Bytes.length) {
        lb.writeBytes(utf8Bytes, 0, utf8Bytes.length);
    } else {
        throw new IllegalArgumentException("Insufficient write space in LinkedBuffer after extension");
    }

    return lb;
}

